#!/usr/bin/env sh
set -eu

OUT_ROOT="${1:-/seed-assets/seed}"
MANIFEST="${2:-/tmp/asset-manifest.txt}"
mkdir -p "$OUT_ROOT"

SAMPLE_THUMBNAIL_240_AVIF=''
SAMPLE_SEARCH_640_AVIF=''
SAMPLE_DETAIL_1600_WEBP=''
SAMPLE_HOME_480_AVIF=''
SAMPLE_ORIGINAL_WEBP=''

while IFS= read -r rel; do
  [ -n "$rel" ] || continue
  dir="$OUT_ROOT/$(dirname "$rel")"
  mkdir -p "$dir"
  case "$(basename "$rel")" in
    thumbnail-240.avif) printf %s "$SAMPLE_THUMBNAIL_240_AVIF" | base64 -d > "$OUT_ROOT/$rel" ;;
    search-640.avif) printf %s "$SAMPLE_SEARCH_640_AVIF" | base64 -d > "$OUT_ROOT/$rel" ;;
    detail-1600.webp) printf %s "$SAMPLE_DETAIL_1600_WEBP" | base64 -d > "$OUT_ROOT/$rel" ;;
    home-480.avif) printf %s "$SAMPLE_HOME_480_AVIF" | base64 -d > "$OUT_ROOT/$rel" ;;
    original.webp) printf %s "$SAMPLE_ORIGINAL_WEBP" | base64 -d > "$OUT_ROOT/$rel" ;;
    *) echo "Unsupported media seed variant: $rel" >&2; exit 1 ;;
  esac
done < "$MANIFEST"

printf 'MEDIA_SEED_GENERATED count=%s\n' "$(wc -l < "$MANIFEST" | tr -d ' ')"
